/// 将 Core tool id 编码为 OpenAI 接受的函数名。
pub fn to_wire_tool_name(name: &str) -> String {
    name.chars()
        .map(|character| match character {
            '.' | ':' => '_',
            character => character,
        })
        .collect()
}

/// 建立线名到原始 Core id 的映射，并拒绝编码后的名称碰撞。
pub fn mappings(names: &[&str]) -> Result<HashMap<String, String>, String> {
    let mut from_wire = HashMap::new();
    for original in names {
        let wire_name = to_wire_tool_name(original);
        if let Some(existing) = from_wire.get(&wire_name) {
            if existing != original {
                return Err(format!(
                    "tool name collision: `{}` and `{}` both map to `{}`",
                    existing, original, wire_name
                ));
            }
        } else {
            from_wire.insert(wire_name, (*original).to_string());
        }
    }
    Ok(from_wire)
}

